head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[checkcombobox > M > checkAll]<br/>컴포넌트에 정의된 전체 아이템을 선택하거나 해제합니다.",
    "validation" : [        
        "disabled 속성으로 컴포넌트가 비활성화 상태여도 전체 아이템의 선택 상태가 변경됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
            target1.remove();
    }

    let properties = {
        disabled : true,
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onchange"]);

    // comp 생성
    $c.gcm.createBasicCheckComboBox(cList, eList);
}



scwin.btn_getSelectedInfo_onclick = function (e) {
    let rtn = target1.getSelectedInfo();

    // 배열의 각 요소를 순회합니다.
    for (let i = 0; i < rtn.length; i++) {
        let item = rtn[i]; // 현재 요소를 가져옵니다.

        // index, label, value, checked 값을 가져옵니다.
        let index = item.index;
        let label = item.label;
        let value = item.value;
        let checked = item.checked;

        // 원하는 작업을 수행할 수 있습니다.
        wf_body_bottom.getObj("scwin").setReturnValue("Index:"+index+", Label:"+label+", Value:"+value+ ", Checked:"+checked);
    }    
};



scwin.target1_onchange = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onchange=====");	
}



scwin.btn_checkAll_onclick = function (e) {
    let checked = par_checked.getText();

    if (checked == "true")
	    target1.checkAll(true);
    else if (checked == "false")
        target1.checkAll(false);
    else
        target1.checkAll();
};
